{
  "reviewer": "Reviewer - No Persona",
  "decision": "Accept",
  "scores": {
    "novelty": 5,
    "soundness": 4,
    "significance": 5,
    "evaluation": 4,
    "clarity": 4
  },
  "strengths": [
    "The paper introduces a novel and principled Riemannian geometry framework to systematically account for continuous parameter symmetries in neural networks, specifically addressing the failure of prior sharpness measures for transformers.",
    "The proposed geodesic sharpness measure demonstrates a strong and consistent correlation with generalization on challenging real-world tasks (ImageNet, MNLI) where previous measures (like adaptive sharpness) failed or showed weak correlation.",
    "The work provides a significant theoretical unification, showing that prior adaptive sharpness measures are first-order approximations within this more general Riemannian framework, thereby explaining their limitations."
  ],
  "weaknesses": [
    "The correlation between the proposed geodesic sharpness and generalization shows an inconsistent sign (negative for some tasks, positive for others), which is not fully explained and limits its direct utility as a regularizer.",
    "The computational complexity, particularly for the 'inv' metric which requires solving Sylvester equations, might be a barrier for very large-scale applications despite the authors' claims of efficiency."
  ],
  "weakness_details": [
    {
      "weakness": "The correlation between the proposed geodesic sharpness and generalization shows an inconsistent sign (negative for some tasks, positive for others), which is not fully explained and limits its direct utility as a regularizer.",
      "severity": "major",
      "evidence": "Section 7 (Remarks, Limitations & Future Work) states: 'the sign of the correlation between geodesic sharpness and generalization varies depending on the setting and is at times negative... This artifact is not inherent to our proposed metrics.' Table 1 shows negative τ for ImageNet and diagonal nets, but positive τ for MNLI.",
      "affected_claim": "The claim that geodesic sharpness is a reliable predictor of generalization, which is central to the paper's contribution.",
      "fixable_without_substantial_new_work": false
    },
    {
      "weakness": "The computational complexity, particularly for the 'inv' metric which requires solving Sylvester equations, might be a barrier for very large-scale applications despite the authors' claims of efficiency.",
      "severity": "minor",
      "evidence": "Section C.3 (Complexity) states: 'For ⟨·, ·⟩inv, Step 3) requires solving a Sylvester equation to project the direction... This solve is cubic in h'. While h is argued to be small, this is an additional cost compared to baseline methods.",
      "affected_claim": "The claim that the approach is practical and computationally feasible for modern architectures.",
      "fixable_without_substantial_new_work": true
    }
  ],
  "acceptance_gates": {
    "soundness": {
      "result": "pass",
      "justification": "The theoretical framework is grounded in established Riemannian geometry. The derivation of symmetries, quotient manifolds, horizontal lifts, and geodesics is sound. Experimental results on synthetic (diagonal nets) and real-world (transformers) tasks consistently support the central claims."
    },
    "novelty": {
      "result": "pass",
      "justification": "The application of Riemannian quotient manifolds to systematically handle high-dimensional transformer symmetries (like GL(h)) is novel. This provides a general 'recipe' that subsumes prior ad-hoc fixes (like adaptive sharpness) as special cases."
    },
    "significance": {
      "result": "pass",
      "justification": "The work successfully addresses a known failure mode of a central concept (sharpness) for a dominant architecture (transformers). Restoring a strong correlation with generalization on large-scale tasks like ImageNet and MNLI is a significant advancement for the field."
    },
    "evaluation": {
      "result": "pass",
      "justification": "Evaluation is comprehensive, covering synthetic settings (diagonal nets with analytical checks) and large-scale real-world tasks (vision and language transformers). Comparisons are made against strong baselines (adaptive sharpness, relative sharpness). The correlation strength is convincingly demonstrated."
    },
    "presentation": {
      "result": "pass",
      "justification": "The paper is generally well-written, with clear motivations, theoretical explanations, and experimental descriptions. Figures effectively illustrate concepts and results. The mathematical framework, while complex, is explained with sufficient detail and supporting appendices."
    }
  ],
  "summary_comment": "This paper makes a strong and novel contribution by introducing a Riemannian geometric framework to define sharpness on quotient manifolds, effectively accounting for the rich symmetries in transformers. This principled approach not only explains the limitations of prior measures but also demonstrates a restored, strong correlation with generalization on challenging benchmarks. While the inconsistent sign of the correlation is a notable weakness, it is presented as an intriguing finding for future work rather than a fatal flaw. The paper clearly meets the high standard of a top-tier conference."
}

