reviewers.raw:
{
  "reviewer": "Reviewer - No Persona",
  "decision": "Reject",
  "scores": {
    "novelty": 3,
    "soundness": 2,
    "significance": 3,
    "evaluation": 2,
    "clarity": 3
  },
  "strengths": [
    "Proposes a novel integration of block coordinate descent with Hessian-informed zeroth-order optimization for memory-efficient LLM fine-tuning",
    "Demonstrates practical memory reduction (up to 39%) compared to HiZOO while maintaining comparable accuracy",
    "Addresses an important problem of memory-constrained fine-tuning for large language models"
  ],
  "weaknesses": [
    "Lack of theoretical foundation and proper convergence analysis for the proposed BCD variant",
    "Insufficient experimental validation and comparison with state-of-the-art methods"
  ],
  "weakness_details": [
    {
      "weakness": "Lack of theoretical foundation and proper convergence analysis for the proposed BCD variant",
      "severity": "major",
      "evidence": "The convergence analysis in Section 4.2 is directly adapted from HiZOO without justification for the BCD modification. The paper states 'our proposed B-PDF preserves its convergence properties' but provides no theoretical analysis of how block coordinate descent affects convergence.",
      "affected_claim": "Claim that the method maintains convergence properties while reducing memory",
      "fixable_without_substantial_new_work": false
    },
    {
      "weakness": "Insufficient experimental validation and comparison with state-of-the-art methods",
      "severity": "major",
      "evidence": "Experiments only compare against basic baselines (SGD, MeZO, HiZOO) but miss comparisons with recent memory-efficient methods like GaLore or other BCD approaches. The LLaMA-2-7B experiments are limited to one dataset with incomplete results due to memory constraints.",
      "affected_claim": "Claim that the method offers practical advantages over existing approaches",
      "fixable_without_substantial_new_work": true
    }
  ],
  "acceptance_gates": {
    "soundness": {
      "result": "fail",
      "justification": "The theoretical foundation is weak - convergence analysis is directly copied from HiZOO without proper adaptation to the BCD framework. The method's mathematical soundness is not adequately established."
    },
    "novelty": {
      "result": "pass",
      "justification": "The integration of BCD with Hessian-informed zeroth-order optimization is novel and represents a meaningful combination of existing techniques."
    },
    "significance": {
      "result": "fail",
      "justification": "While the problem is important, the demonstrated improvements are incremental (39% memory reduction over HiZOO but similar accuracy to MeZO). The method doesn't clearly advance the field beyond existing approaches."
    },
    "evaluation": {
      "result": "fail",
      "justification": "Experimental validation is insufficient - limited comparisons, incomplete results on larger models, and lack of comparison with recent state-of-the-art methods. The memory savings claim is supported but convergence benefits are not clearly demonstrated."
    },
    "presentation": {
      "result": "pass",
      "justification": "The paper is generally well-written and organized, though some sections (like the convergence analysis) are poorly justified."
    }
  ],
  "summary_comment": "The paper proposes an interesting idea of combining block coordinate descent with Hessian-informed zeroth-order optimization for memory-efficient LLM fine-tuning. While the concept has merit and addresses an important problem, the submission suffers from major weaknesses: (1) lack of proper theoretical foundation for the BCD variant, (2) insufficient experimental validation against state-of-the-art methods, and (3) incremental improvements that don't clearly advance the field. The memory reduction is demonstrated but convergence benefits are not convincingly shown. For a top-tier conference, the paper requires more rigorous theoretical analysis and comprehensive experimental evaluation."
}

